const $=id=>document.getElementById(id);let reverse=false;
const count=s=>Array.from(s).length;
function update(){const value=$('input').value;$('output').value=convert(value,reverse);$('input-count').textContent=`${count(value)} belgi · ${value.trim()?value.trim().split(/\s+/).length:0} so‘z`;$('output-count').textContent=`${count($('output').value)} belgi`;$('copy').disabled=$('download').disabled=!value;$('status').textContent=value?'Tayyor · Matn o‘girildi':'Yozishni boshlang';}
function direction(value){reverse=value;for(const [id,on] of [['forward',!value],['reverse',value]]){$(id).classList.toggle('active',on);$(id).setAttribute('aria-pressed',on);}$('input-label').textContent=value?'Yangi yozuv':'Amaldagi yozuv';$('output-label').textContent=value?'Amaldagi yozuv':'Yangi yozuv';$('output').placeholder=value?'Amaldagi yozuvdagi matningiz shu yerda ko‘rinadi…':'Yangi yozuvdagi matningiz shu yerda ko‘rinadi…';update();}
$('input').addEventListener('input',update);$('forward').onclick=()=>direction(false);$('reverse').onclick=()=>direction(true);$('clear').onclick=()=>{$('input').value='';update();$('input').focus();};$('example').onclick=()=>{const sample='O‘zbekiston — go‘zal o‘lka. Shaharlar, bog‘lar va ochiq ko‘ngilli insonlar.\nHar bir o‘zgarish yangi imkoniyat!';$('input').value=reverse?convert(sample):sample;update();};$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('output').value);$('status').textContent='Nusxa olindi!';}catch{$('output').focus();$('output').select();$('status').textContent='Nusxa olish uchun Ctrl+C yoki ⌘C bosing.';}};$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([$ ('output').value],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='alifbo-matn.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='TXT fayl tayyor';};update();
